//! Phone durations: `base duration of the sound x context factors`.
//!
//! @generated by tools/fit_durations.py — fitted by least squares (on log duration) to
//! 16311 labelled phones from two speakers of the CMU Arctic corpus. On held-out sentences
//! the hand-written rules this replaced were off by a factor of e^0.54 on average; this model
//! by e^0.38 (the rest is speakers simply not timing a word the same way twice).

use crate::phone::Ph;

/// What the timeline knows about a phone's surroundings.
pub(crate) struct Context {
    pub stress: u8,
    /// False for function words (the, of, and ...) that are not phrase-final.
    pub is_content: bool,
    pub word_initial: bool,
    pub word_final: bool,
    /// The phone belongs to the last word before a pause.
    pub phrase_final_word: bool,
    /// The phone belongs to the word carrying the phrase's main accent.
    pub nuclear: bool,
    pub n_sylls: usize,
    /// No vowel follows inside the word (last syllable, or its coda).
    pub last_syllable: bool,
    /// Stress of the syllable a consonant leads into (0 if none in this word).
    pub onset_stress: u8,
    /// Neighbouring phones within the phrase (`Ph::SIL` at its edges).
    pub prev: Ph,
    pub next: Ph,
    pub prev_same_word: bool,
    pub next_same_word: bool,
}

/// Duration in ms of a stressed vowel in a one-syllable content word before a voiced
/// consonant, or of a word-medial single consonant.
pub(crate) fn base_ms(ph: Ph) -> f64 {
    match ph {
        Ph::AA => 78.3,
        Ph::AE => 82.3,
        Ph::AH => 59.2,
        Ph::AO => 96.9,
        Ph::AW => 113.1,
        Ph::AX => 49.6,
        Ph::AY => 114.2,
        Ph::B => 54.6,
        Ph::CH => 105.5,
        Ph::D => 46.2,
        Ph::DH => 42.7,
        Ph::EH => 64.8,
        Ph::ER => 98.4,
        Ph::EY => 106.5,
        Ph::F => 77.1,
        Ph::G => 61.8,
        Ph::HH => 47.1,
        Ph::IH => 52.7,
        Ph::IY => 84.8,
        Ph::JH => 90.5,
        Ph::K => 76.8,
        Ph::L => 77.5,
        Ph::M => 66.4,
        Ph::N => 57.9,
        Ph::NG => 82.7,
        Ph::OW => 96.2,
        Ph::OY => 138.8,
        Ph::P => 74.5,
        Ph::R => 63.5,
        Ph::S => 93.0,
        Ph::SH => 111.4,
        Ph::T => 54.2,
        Ph::TH => 76.2,
        Ph::UH => 48.1,
        Ph::UW => 71.4,
        Ph::V => 60.0,
        Ph::W => 65.4,
        Ph::Y => 54.7,
        Ph::Z => 79.5,
        Ph::ZH => 98.4,
        Ph::SIL => 80.0,
    }
}

const V_UNSTRESSED: f64 = 0.683; // unstressed vowel in a content word
const V_SECONDARY: f64 = 0.865; // secondary stress
const V_FUNCTION: f64 = 0.676; // vowel of a (non-final) function word
const V_NUCLEAR: f64 = 1.116; // the phrase's main accent
const V_PHRASE_FINAL_SYLLABLE: f64 = 1.695; // last syllable before a pause
const V_PHRASE_FINAL_WORD: f64 = 1.062; // earlier syllables of the last word
const V_WORD_FINAL_SYLLABLE: f64 = 1.208; // last syllable of a longer word
const V_PHRASE_FINAL_OPEN: f64 = 1.494; // nothing after the vowel at all
const V_BEFORE_VOWEL: f64 = 1.455; // hiatus
const V_BEFORE_LIQUID: f64 = 0.819; // the liquid/glide takes over part of the vowel
const V_WORD_INITIAL: f64 = 1.230; // word starts with this vowel
const C_INITIAL_CONTENT: f64 = 1.186; // first sound of a content word
const C_INITIAL_FUNCTION: f64 = 1.404; // first sound of a function word
const C_FINAL: f64 = 1.155; // last sound of a word
const C_AFTER_CONSONANT: f64 = 0.868; // second member of a cluster
const C_BEFORE_CONSONANT: f64 = 1.083; // first member of a cluster
const C_PHRASE_FINAL: f64 = 1.741; // the very last sound before a pause
const C_PHRASE_FINAL_CODA: f64 = 1.326; // other coda consonants of the last syllable
const C_STRESSED_ONSET: f64 = 1.258; // starts a stressed syllable
const C_FUNCTION: f64 = 0.848; // inside a function word
const C_FLAP: f64 = 0.857; // t/d between vowels before an unstressed syllable

fn is_approximant(ph: Ph) -> bool {
    matches!(ph, Ph::L | Ph::R | Ph::W | Ph::Y)
}

/// Natural duration in milliseconds of `ph` in context `c`, at a normal speaking rate.
pub(crate) fn duration_ms(ph: Ph, c: &Context) -> f64 {
    let mut d = base_ms(ph);
    let phrase_final = c.next == Ph::SIL;
    if ph.is_vowel() {
        d *= match (c.is_content, c.stress) {
            (_, 1) => 1.0,
            (_, 2) => V_SECONDARY,
            (true, _) => V_UNSTRESSED,
            (false, _) => V_FUNCTION,
        };
        if c.nuclear && c.stress == 1 {
            d *= V_NUCLEAR;
        }
        if c.phrase_final_word {
            d *= if c.last_syllable { V_PHRASE_FINAL_SYLLABLE } else { V_PHRASE_FINAL_WORD };
        } else if c.last_syllable && c.n_sylls > 1 {
            d *= V_WORD_FINAL_SYLLABLE;
        }
        if phrase_final {
            d *= V_PHRASE_FINAL_OPEN;
        } else if c.next.is_vowel() {
            d *= V_BEFORE_VOWEL;
        } else if is_approximant(c.next) {
            d *= V_BEFORE_LIQUID;
        }
        if !c.prev_same_word {
            d *= V_WORD_INITIAL;
        }
    } else {
        let after_consonant = c.prev_same_word && !c.prev.is_vowel();
        let before_consonant = c.next_same_word && !c.next.is_vowel();
        if c.word_initial {
            d *= if c.is_content { C_INITIAL_CONTENT } else { C_INITIAL_FUNCTION };
        } else if c.word_final {
            d *= C_FINAL;
        }
        if after_consonant {
            d *= C_AFTER_CONSONANT;
        }
        if before_consonant {
            d *= C_BEFORE_CONSONANT;
        }
        if c.phrase_final_word && c.last_syllable {
            d *= if phrase_final { C_PHRASE_FINAL } else { C_PHRASE_FINAL_CODA };
        }
        if !c.last_syllable && c.onset_stress == 1 && !before_consonant {
            d *= C_STRESSED_ONSET;
        }
        if !c.is_content {
            d *= C_FUNCTION;
        }
        if matches!(ph, Ph::T | Ph::D)
            && c.prev.is_vowel()
            && c.next.is_vowel()
            && c.onset_stress != 1
            && !c.word_initial
        {
            d *= C_FLAP;
        }
    }
    d
}
